local config = {
  ui_story_5034_50340000_1_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5034_50340000_2_dialog_content = "Oh não! Você está bem?",
  ui_story_5034_50340000_3_dialog_content = "Eu estou bem...",
  ui_story_5034_50340000_4_dialog_content = "Huh? É você, Sr. Navegador!",
  ui_story_5034_50340000_5_dialog_content = "Olá, <color=#FFB400>Schewe</color>.",
  ui_story_5034_50340000_6_dialog_content = "Você sabe que pode me chamar pelo meu nome, certo? Como Nekoyashiki e os outros fazem.",
  ui_story_5034_50340000_7_dialog_content = "O que? De jeito nenhum!",
  ui_story_5034_50340000_8_dialog_content = "Você é mais velho que eu, e eu tenho que respeitar meus mais velhos!",
  ui_story_5034_50340000_9_dialog_content = "Er... Ok, então.",
  ui_story_5034_50340000_10_dialog_content = "O que acharam do doce? Ficou gostoso?",
  ui_story_5034_50340000_11_dialog_content = "O-Claro! Foi absolutamente delicioso!",
  ui_story_5034_50340000_12_dialog_content = "É o nosso doce favorito! Obrigado, Sr. Navegador!",
  ui_story_5034_50340000_13_dialog_content = "Schewe está mentindo! Ele não comeu nada!",
  ui_story_5034_50340000_14_dialog_content = "Latão! Mr. Navigator e eu estamos conversando, vá embora!",
  ui_story_5034_50340000_15_dialog_content = "Mas você mentiu, Schewe! Você me deu o doce...",
  ui_story_5034_50340000_16_dialog_content = "Lembra-se do que Pollux nos disse? Não devemos mentir para as pessoas que são gentis conosco!",
  ui_story_5034_50340000_17_dialog_content = "Eu não queria mentir, agora caia fora!",
  ui_story_5034_50340000_18_dialog_content = "Schewe... Você me pediu aquele doce para fazer Latan se sentir melhor?",
  ui_story_5034_50340000_19_dialog_content = "Acho que não há como passar por você, Sr. Navegador. Me desculpe, eu não deveria ter mentido em primeiro lugar.",
  ui_story_5034_50340000_20_dialog_content = "Sr. Navegador? Eu realmente quero que Schewe coma alguns doces também.",
  ui_story_5034_50340000_21_dialog_content = "Se eu soubesse que havia apenas um pedaço, não teria comido tudo em uma mordida...",
  ui_story_5034_50340000_22_dialog_content = "Não seja um incômodo, Latan. Estou bem sem.",
  ui_story_5034_50340000_23_dialog_content = "Só de ver você de volta ao seu antigo eu me sinto mais feliz do que comer qualquer doce!",
  ui_story_5034_50340000_24_dialog_content = "Tudo bem, crianças. Isso vai servir por enquanto.",
  ui_story_5034_50340000_25_dialog_content = "É só um doce, sabe? Comprar doces não é grande coisa para alguém crescido como eu.",
  ui_story_5034_50340000_26_dialog_content = "Mas só Nekoyashiki tem esse tipo de doce... Não encontramos em Euphoria.",
  ui_story_5034_50340000_27_dialog_content = "Se Nekoyashiki pode colocar as mãos nele de alguma forma, então por que eu não posso? Dê-me algum crédito, pessoal!",
  ui_story_5034_50340000_28_dialog_content = "Apenas espere, eu vou trazer tantos doces para você que você não vai conseguir terminar tudo!",
  ui_story_5034_50340000_29_dialog_content = "Yay! Você é o melhor, Sr. Navegador! Ninguém é mais legal do que você!",
  ui_story_5034_50340000_30_dialog_content = "Ei, Latan, não diga isso...",
  ui_story_5034_50340000_31_dialog_content = "E se o Sr. Navegador não conseguir encontrar o doce?",
  ui_story_5034_50340000_32_dialog_content = "Obrigado pelo voto de confiança, Schewe...",
  ui_story_5034_50340000_33_dialog_content = "De qualquer forma, os adultos devem sempre cumprir suas promessas para as crianças. Vocês dois apenas esperem aqui por mim, e eu estarei de volta em breve.",
  ui_story_5034_50340000_34_dialog_content = "(Agora onde devo ir procurar aquele doce...?)",
  ui_story_5034_50340000_35_dialog_content = "(Ah, sim! Aposto que ela teria alguma ideia!)",
  ui_story_5034_50340000_36_dialog_content = "Hum? Já se sentindo descansado, eu vejo?",
  ui_story_5034_50340000_37_dialog_content = "Definitivamente! Eu me sinto perfeitamente bem agora.",
  ui_story_5034_50340000_38_dialog_content = "A propósito, Pollux... Há algo que gostaria de lhe perguntar.",
  ui_story_5034_50340000_39_dialog_content = "Você sabe onde posso encontrar mais desse doce que as crianças gostam?",
  ui_story_5034_50340000_40_dialog_content = "Você está falando sobre o doce que Nekoyashiki geralmente traz, certo?",
  ui_story_5034_50340000_41_dialog_content = "Não o vi em nenhum lugar em Euphoria, o que significa que ele deve estar trazendo de algum outro lugar.",
  ui_story_5034_50340000_42_dialog_content = "Mas por que você não vai e pergunta a ele você mesmo? Acho que ele ainda não saiu.",
  ui_story_5034_50340000_43_option_content = "Sem chance!",
  ui_story_5034_50340000_44_dialog_content = "Além disso, é apenas doce. Se ele pode pegá-lo, então eu também posso.",
  ui_story_5034_50340000_45_dialog_content = "Contanto que ele não faça isso sozinho, tenho certeza que posso encontrar uma maneira de comprar alguns!",
  ui_story_5034_50340000_46_option_content = "Parece que não tenho escolha a não ser perguntar a ele...",
  ui_story_5034_50340000_47_dialog_content = "Não há realmente nenhuma outra maneira ...?",
  ui_story_5034_50340000_48_dialog_content = "Obrigado, Pollux.",
  ui_story_5034_50340000_49_dialog_content = "Espere, PlayerName. Acabei de me lembrar de uma certa loja na cidade que está no mercado há muito tempo.",
  ui_story_5034_50340000_50_dialog_content = "O lojista é bastante experiente em negócios e traz todos os tipos de mercadorias exóticas para vender aqui na Euphoria.",
  ui_story_5034_50340000_51_dialog_content = "Você pode tentar a sorte lá primeiro.",
  ui_story_5034_50340000_52_dialog_content = "Entendi! Obrigado mais uma vez, Pollux!",
  ui_story_5034_50340000_53_dialog_content = "Ei! Ainda não te disse onde fica a loja!",
  ui_story_5034_50340000_54_dialog_content = "Sempre com tanta pressa...",
  ui_story_5034_50340000_55_dialog_content = "Corax! Onde está você, Corax?",
  ui_story_5034_50340000_56_dialog_content = "Bem atrás de você... O que há com toda essa gritaria?",
  ui_story_5034_50340000_57_dialog_content = "Ahhh! Não me fuja assim!",
  ui_story_5034_50340000_58_dialog_content = "De qualquer forma, você tem um minuto, Corax?",
  ui_story_5034_50340000_59_dialog_content = "Por que pergunta?",
  ui_story_5034_50340000_60_dialog_content = "Eu quero comprar um doce, mas a loja que vende fica na cidade, e eu não quero ir sozinho...",
  ui_story_5034_50340000_61_dialog_content = "Não posso ajudá-lo. Estou indo para um lugar agradável e vago para alimentar os pássaros.",
  ui_story_5034_50340000_62_dialog_content = "Huh? Eu sou realmente menos importante do que um par de pássaros?",
  ui_story_5034_50340000_63_dialog_content = "Oi, Nekoyashiki. Você está bem na hora.",
  ui_story_5034_50340000_64_dialog_content = "PlayerName quer ir à cidade comprar alguns doces. Vai com ele, sim? Eu não tenho tempo para isso.",
  ui_story_5034_50340000_65_dialog_content = "Corax...",
  ui_story_5034_50340000_66_dialog_content = "Ah... Doce, você diz?",
  ui_story_5034_50340000_67_dialog_content = "Então aquele doce que eu te dei antes... Você comeu sozinho ao invés de dar para as crianças, não foi?",
  ui_story_5034_50340000_68_dialog_content = "Não sabia que esse era o tipo de pessoa que você era, PlayerName...",
  ui_story_5034_50340000_69_dialog_content = "Não deixe sua imaginação correr solta! Eu só queria comprar mais para as crianças, só isso.",
  ui_story_5034_50340000_70_dialog_content = "Mas como você já está aqui, me poupa o trabalho de ir à cidade.",
  ui_story_5034_50340000_71_dialog_content = "Se você tem mais desse doce, por que não vende tudo para mim?",
  ui_story_5034_50340000_72_dialog_content = "Eu adoraria ajudá-lo a parecer legal na frente das crianças, PlayerName...",
  ui_story_5034_50340000_73_dialog_content = "Mas, infelizmente, já dei ou comi o resto do doce.",
  ui_story_5034_50340000_74_dialog_content = "Aquela peça que te dei foi a última.",
  ui_story_5034_50340000_75_dialog_content = "Realmente... Parece que vou ter que tentar a sorte naquela loja, afinal...",
  ui_story_5034_50340000_76_dialog_content = "\"Aquela loja\"?",
  ui_story_5034_50340000_77_dialog_content = "Eu não fazia ideia de que havia uma loja em Euphoria que vendesse esse tipo de doce... Agora estou bem curiosa para ver eu mesmo.",
  ui_story_5034_50340000_78_dialog_content = "Perguntei a Pollux, e ela me contou sobre uma loja na cidade que importa todos os tipos de mercadorias exóticas. Vou ver se acho lá.",
  ui_story_5034_50340000_79_dialog_content = "<size=30>Ah... aquela loja...</size>",
  ui_story_5034_50340000_80_dialog_content = "Merda, espere um minuto... Eu esqueci totalmente de perguntar ao Pollux onde fica.",
  ui_story_5034_50340000_81_dialog_content = "Eu me pergunto se ela ainda está na entrada...",
  ui_story_5034_50340000_82_dialog_content = "Eu sei onde é. Venha, eu te levo até lá.",
  ui_story_5034_50340000_83_dialog_content = "O que...? Você vai comigo?",
  ui_story_5034_50340000_84_dialog_content = "Só estou curioso para ver se o lojista tem o que é preciso para conseguir esse tipo de doce, só isso.",
  ui_story_5034_50340000_85_dialog_content = "Acontece que estamos indo na mesma direção.",
  ui_story_5034_50340000_86_dialog_content = "Agora apresse-se, ou vou embora por conta própria.",
  ui_story_5034_50340000_87_dialog_content = "Ei! Espere por mim!",
  ui_story_5034_50340101_1_dialog_content = "Devemos chegar lá em breve, certo? Parece que estamos caminhando para sempre...",
  ui_story_5034_50340101_2_dialog_content = "Sim... Se não me engano, então essa deveria ser a loja que a Pollux estava falando.",
  ui_story_5034_50340101_3_dialog_content = "Venha, vamos entrar e dar uma olhada ao redor.",
  ui_story_5034_50340101_4_dialog_content = "Bem, se não for Nekoyashiki... A que devo o prazer de um cliente tão raro?",
  ui_story_5034_50340101_5_dialog_content = "Nunca pensei que uma loja humilde como a minha pudesse trazer algo de interesse para alguém como você.",
  ui_story_5034_50340101_6_dialog_content = "Ah, não ligue para mim, só estou dando uma olhada... Ele, por outro lado, está interessado em comprar alguma coisa.",
  ui_story_5034_50340101_7_dialog_content = "Perdoe-me, mas por acaso você vende algum doce aqui?",
  ui_story_5034_50340101_8_dialog_content = "Você terá que procurá-lo você mesmo. Além disso, não vendemos nada a crédito, então não se preocupe em perguntar.",
  ui_story_5034_50340101_9_dialog_content = "Alguém se levantou do lado errado da cama...",
  ui_story_5034_50340101_10_dialog_content = "Não importa, eu não me importo de olhar por conta própria.",
  ui_story_5034_50340101_11_dialog_content = "Ah! Encontrei! Eu não posso acreditar que está realmente em estoque aqui!",
  ui_story_5034_50340101_12_dialog_content = "Hum? Deixe-me ver isso...",
  ui_story_5034_50340101_13_dialog_content = "Oh? Diga, lojista... De onde exatamente você importou isso?",
  ui_story_5034_50340101_14_dialog_content = "Tentando me tirar do negócio, hein? Você já tem muitos canais para seus produtos, então não há necessidade de eu falar sobre os meus, muito obrigado.",
  ui_story_5034_50340101_15_dialog_content = "Administrar até uma loja pequena como a minha não é fácil, sabe? Tente pensar nas pessoas pequenas de vez em quando, \"Mestre\" Nekoyashiki.",
  ui_story_5034_50340101_16_dialog_content = "Se o negócio é tão difícil, por que você importaria um doce impopular como esse? Você não está preocupado em perder seus lucros?",
  ui_story_5034_50340101_17_dialog_content = "Percebi que as crianças aqui gostam desse doce. Se não posso vendê-los, dou-os às crianças.",
  ui_story_5034_50340101_18_dialog_content = "Ah, entendi.",
  ui_story_5034_50340101_19_dialog_content = "Você olharia para isso? Acho que você não é o único que carrega esse tipo de doce agora, hein?",
  ui_story_5034_50340101_20_dialog_content = "Parece tão... Bem, parabéns estão em ordem, suponho.",
  ui_story_5034_50340101_21_dialog_content = "Eu vou levar tudo, senhor!",
  ui_story_5034_50340101_22_dialog_content = "Esplêndido! Agora, são 3.000 Nightium por saco, para um total de...",
  ui_story_5034_50340101_23_dialog_content = "Espere um segundo! Você disse 3.000 Nightium por saco?!",
  ui_story_5034_50340101_24_dialog_content = "*Risada*",
  ui_story_5034_50340101_25_dialog_content = "Por que sim, foi o que eu disse. Cada saco deste doce em particular custa 3.000 Nightium.",
  ui_story_5034_50340101_26_dialog_content = "Mas se você comprar todo o meu estoque, eu vou colocar uma sacola grande para você levar para casa.",
  ui_story_5034_50340101_27_dialog_content = "Mas como poderia um único saco de doces custar 3.000 Nightium, para começar?",
  ui_story_5034_50340101_28_dialog_content = "Nekoyashiki, quão rico você é?!",
  ui_story_5034_50340101_29_dialog_content = "Eu nunca disse que comprei meus doces aqui.",
  ui_story_5034_50340101_30_dialog_content = "Então o que você está dizendo... é que esse cara está me enganando, certo?",
  ui_story_5034_50340101_31_dialog_content = "A euforia não tem como produzir doces, entre outras coisas. A maioria dos produtos é importada aqui através de rotas comerciais estabelecidas.",
  ui_story_5034_50340101_32_dialog_content = "Como resultado, a maioria das coisas que você encontra à venda aqui são mais caras do que em outros lugares.",
  ui_story_5034_50340101_33_dialog_content = "Você está me dizendo que 3.000 Nightium por um mísero saco de doces é aceitável para você então?!",
  ui_story_5034_50340101_34_dialog_content = "Não foi isso que eu disse. Estou apenas fornecendo algumas informações básicas para que você se sinta melhor ao fazer suas compras.",
  ui_story_5034_50340101_35_dialog_content = "<size=45>Isso não ajuda em nada.</size>",
  ui_story_5034_50340101_36_dialog_content = "Você é mais do que bem-vindo para comprar sacos individuais de doces, se quiser? Concedido, a sacola estará fora de questão...",
  ui_story_5034_50340101_37_dialog_content = "(Acho que não tenho escolha. Eu prometi às crianças, afinal... 3.000 Nightium por saco, eu deveria poder pagar pelo menos um... Certo?)",
  ui_story_5034_50340101_38_dialog_content = "Eu... eu só tenho 150 Nightium comigo.",
  ui_story_5034_50340101_39_dialog_content = "Não olhe para mim, trago minha cabeça quando saio de casa, não meu dinheiro.",
  ui_story_5034_50340101_40_dialog_content = "Se ao menos estivéssemos em Umbraton... Eu conseguiria pelo menos cinco sacos de doces por 150 Nightium!",
  ui_story_5034_50340101_41_dialog_content = "Ninguém aqui faz nada sobre esses preços exorbitantes?",
  ui_story_5034_50340101_42_dialog_content = "Mas não estamos em Umbraton, estamos? Estamos na Euphoria, então você tem que jogar pelas regras da Euphoria.",
  ui_story_5034_50340101_43_dialog_content = "E para que não se esqueça, meu amigo, não vendemos nada a crédito nesta loja.",
  ui_story_5034_50340101_44_dialog_content = "Se você não está comprando nada, estou devolvendo essas coisas para as prateleiras.",
  ui_story_5034_50340101_45_dialog_content = "(Se eu não encontrar uma maneira de trazer de volta esse doce, Schewe e Latan ficarão muito desapontados.)",
  ui_story_5034_50340101_46_dialog_content = "(E depois de tudo que eu disse também...)",
  ui_story_5034_50340101_47_dialog_content = "Eu gostaria de comprar uma bolsa, senhor... Mas eu realmente não tenho dinheiro suficiente comigo.",
  ui_story_5034_50340101_48_dialog_content = "Talvez eu possa trocar algo por uma bolsa?",
  ui_story_5034_50340101_49_dialog_content = "Entendo... Bem, eu não gostaria de recusar um amigo de Nekoyashiki tão rudemente.",
  ui_story_5034_50340101_50_dialog_content = "Como é isso? Por que você não fica um pouco e trabalha para mim, e eu te dou aquele saco de doces como pagamento pela sua ajuda? Isso soa justo?",
  ui_story_5034_50340101_51_dialog_content = "Parece um negócio! Então, o que exatamente você precisa que eu faça?",
  ui_story_5034_50340101_52_dialog_content = "Não posso dizer que tenho muita experiência de trabalho, mas prometo que sou um dos melhores do Astra.",
  ui_story_5034_50340101_53_dialog_content = "Eu deveria ir agora. Boa sorte, <color=#FFB400>tempo parcial</color>.",
  ui_story_5034_50340102_1_dialog_content = "(Quando finalmente olhei para o relógio, uma manhã inteira havia quase se passado.)",
  ui_story_5034_50340102_2_dialog_content = "(Abastecer e organizar prateleiras, varrer a loja... Ele até queria que eu atraisse clientes.)",
  ui_story_5034_50340102_3_dialog_content = "(Mas quem compraria em uma loja com preços tão insanos?)",
  ui_story_5034_50340102_4_dialog_content = "Bem, jovem?",
  ui_story_5034_50340102_5_dialog_content = "Agora você sabe como é difícil administrar uma loja em Euphoria.",
  ui_story_5034_50340102_6_dialog_content = "Mesmo assim, eu não gostaria de dificultar as coisas para um amigo de Nekoyashiki...",
  ui_story_5034_50340102_7_dialog_content = "(Você está brincando comigo? Tenho certeza que você está fazendo isso PRECISO porque eu o conheço!)",
  ui_story_5034_50340102_8_dialog_content = "(Não é preciso dizer, mas nunca mais volto a esta loja!)",
  ui_story_5034_50340102_9_dialog_content = "Aqui está você, então, um saco de doces como pagamento pelo seu trabalho duro.",
  ui_story_5034_50340102_10_dialog_content = "Não sei se devo agradecer ou não...",
  ui_story_5034_50340102_11_dialog_content = "Não é necessário agradecer... Mas tente se lembrar de trazer mais dinheiro da próxima vez.",
  ui_story_5034_50340102_12_dialog_content = "Oh, você não precisa se preocupar com isso... definitivamente não haverá uma próxima vez!",
  ui_story_5034_50340102_13_dialog_content = "De qualquer forma, pelo menos eu peguei o doce.",
  ui_story_5034_50340102_14_dialog_content = "É só um saco, mas eu peguei. Agora Schewe pode desfrutar de alguns também!",
  ui_story_5034_50340102_15_dialog_content = "Hum? Espere um minuto, há algo impresso na bolsa...",
  ui_story_5034_50340102_16_dialog_content = "\"Produzido por Especialidades do Extremo Oriente em Umbraton...\"",
  ui_story_5034_50340102_17_dialog_content = "\"Preço de varejo sugerido: 30 Nightium...\"",
  ui_story_5034_50340102_18_dialog_content = "<size=45>O quê?!</size>",
  ui_story_5034_50340102_19_dialog_content = "Eu escravizei minha manhã inteira para comprar um saco de 3.000 Nightium de doces, mas depois de tudo isso...",
  ui_story_5034_50340102_20_dialog_content = "<size=45>Era apenas doces baratos da Umbraton o tempo todo?</size>",
  ui_story_5034_50340102_21_dialog_content = "Você olharia para isso? Acho que você não é o único que carrega esse tipo de doce agora, hein?",
  ui_story_5034_50340102_22_dialog_content = "Parece tão... Bem, parabéns estão em ordem, suponho.",
  ui_story_5034_50340102_23_dialog_content = "Ele sabia! Ele sabia, mas não se deu ao trabalho de me contar!",
  ui_story_5034_50340102_24_dialog_content = "<color=#e8d9bb>*Resmungos*</color>",
  ui_story_5034_50340102_25_dialog_content = "Ugh... estou morrendo de fome depois de tanto trabalho...",
  ui_story_5034_50340102_26_dialog_content = "É quase meio-dia. Se eu me apressar de volta, devo ser capaz de chegar a tempo de almoçar com as crianças.",
  ui_story_5034_50340102_27_dialog_content = "Vou deixar esse lojista desonesto fora do gancho por enquanto... Entregar esse doce para as crianças é muito mais importante agora.",
  ui_story_5034_50340102_28_dialog_content = "Mas guarde as minhas palavras, da próxima vez que o vir... vou dar-lhe uma pequena lição sobre comércio justo!",
  ui_story_5034_50340102_29_dialog_content = "Olha, Schewe! O Sr. Navegador realmente conseguiu encontrar alguns desses doces!",
  ui_story_5034_50340102_30_dialog_content = "Você poderá experimentar alguns também!",
  ui_story_5034_50340102_31_dialog_content = "Mas ele trabalhou duro a manhã toda por aquele doce...",
  ui_story_5034_50340102_32_dialog_content = "É verdade... Seguimos o Sr. Navegador porque queríamos ver onde ele conseguiu o doce.",
  ui_story_5034_50340102_33_dialog_content = "Ele disse que ia nos comprar lotes também...",
  ui_story_5034_50340102_34_dialog_content = "Eu sabia que ele realmente não quis dizer isso.",
  ui_story_5034_50340102_35_dialog_content = "Mas se ao menos não tivéssemos parecido tão desesperados para comer o doce...",
  ui_story_5034_50340102_36_dialog_content = "Ele não teria que trabalhar para aquele lojista malvado só para comprar para nós.",
  ui_story_5034_50340102_37_dialog_content = "Eu estava errado, Latan... eu não mereço comer o doce...",
  ui_story_5034_50340102_38_dialog_content = "Schewe...",
  ui_story_5034_50340102_39_dialog_content = "Espere! Eu tenho uma ideia!",
  ui_story_5034_50340102_40_dialog_content = "Uma ideia...?",
  ui_story_5034_50340102_41_dialog_content = "Se o Sr. Navigator pôde trabalhar naquela loja, nós também podemos!",
  ui_story_5034_50340102_42_dialog_content = "Quer dizer que também podemos trabalhar pelos doces?",
  ui_story_5034_50340102_43_dialog_content = "Isso mesmo! Dessa forma, o Sr. Navegador não vai pensar que somos apenas um casal de crianças egoístas!",
  ui_story_5034_50340102_44_dialog_content = "Não podemos ficar aqui e esperar que ele traga doces para nós.",
  ui_story_5034_50340102_45_dialog_content = "Ele também merece aproveitar os frutos do nosso trabalho duro!",
  ui_story_5034_50340102_46_dialog_content = "E com nós dois, devemos ganhar duas malas em vez de uma! Mas o que devemos fazer com a segunda bolsa?",
  ui_story_5034_50340102_47_dialog_content = "Por que não dar de presente à Pollux? Ela trabalha duro para cuidar de nós também... Devemos mostrar a ela nossa gratidão!",
  ui_story_5034_50340102_48_dialog_content = "Então está resolvido! Quanto àquele que odeia doces, Casta... Devemos usar nosso <color=#FFB400>truque de sempre</color>?",
  ui_story_5034_50340102_49_dialog_content = "Bem, isso não será fácil, Latan.",
  ui_story_5034_50340102_50_dialog_content = "Eu sei! Apenas deixe comigo!",
  ui_story_5034_50340201_1_dialog_content = "Ah, você voltou.",
  ui_story_5034_50340201_2_dialog_content = "Eu pensei que você tinha saído só para pegar doces? Por que você está tão suado?",
  ui_story_5034_50340201_3_dialog_content = "\"Só para pegar doces\", minha bunda...",
  ui_story_5034_50340201_4_dialog_content = "Você viu Nekoyashiki? Eu preciso \"agradecer\" a ele corretamente por me ajudar.",
  ui_story_5034_50340201_5_dialog_content = "Eu não o vi por aqui. Vocês dois não saíram juntos?",
  ui_story_5034_50340201_6_dialog_content = "<color=#e8d9bb>*Resmungos*</color>",
  ui_story_5034_50340201_7_dialog_content = "Ah... Com tanta fome... Acho que vou deixá-lo em paz por enquanto.",
  ui_story_5034_50340201_8_dialog_content = "O almoço já está pronto? O que temos hoje?",
  ui_story_5034_50340201_9_dialog_content = "Desculpe, mas todos terminaram de almoçar há um tempo atrás.",
  ui_story_5034_50340201_10_dialog_content = "O que?! E ninguém pensou em deixar um pouco para mim?!",
  ui_story_5034_50340201_11_dialog_content = "Você tem um saco de doces na mão, não é? Apenas coma alguns pedaços, e isso vai te segurar até o jantar.",
  ui_story_5034_50340201_12_dialog_content = "Não dá, esse doce é para Schewe e Latan, assim como para as outras crianças!",
  ui_story_5034_50340201_13_dialog_content = "Você não tem ideia do que eu passei por esse saco de doces...",
  ui_story_5034_50340201_14_dialog_content = "Falando nisso... onde estão Schewe e Latan, afinal?",
  ui_story_5034_50340201_15_dialog_content = "Você sabe onde esses dois estão, Corax?",
  ui_story_5034_50340201_16_dialog_content = "Você quer dizer as duas crianças que estavam pedindo doces, sim?",
  ui_story_5034_50340201_17_dialog_content = "Sim, esses dois!",
  ui_story_5034_50340201_18_dialog_content = "Eles seguiram você até a cidade, se bem me lembro.",
  ui_story_5034_50340201_19_dialog_content = "Espere o que? Por que eles estavam me seguindo?",
  ui_story_5034_50340201_20_dialog_content = "Depois que você saiu da igreja esta manhã, aqueles dois também partiram logo depois.",
  ui_story_5034_50340201_21_dialog_content = "Eu pensei que vocês estivessem viajando em grupo... Isso significa que vocês nunca os viram enquanto estavam na cidade?",
  ui_story_5034_50340201_22_dialog_content = "Eu não... eu não tinha ideia de que estava sendo seguido. Mas eu já voltei, então onde eles poderiam estar?",
  ui_story_5034_50340201_23_dialog_content = "Não surte, tenho certeza que eles estão onde você foi pela última vez.",
  ui_story_5034_50340201_24_dialog_content = "Você tem razão! Eu deveria voltar e procurá-los!",
  ui_story_5034_50340201_25_dialog_content = "Já volto, Corax! Fique de olho nas outras crianças para mim, sim?",
  ui_story_5034_50340201_26_dialog_content = "Ei! Tome isso também!",
  ui_story_5034_50340201_27_dialog_content = "Isso é... <color=#FFB400>meio pão</color>?",
  ui_story_5034_50340201_28_dialog_content = "É um pouco obsoleto, mas terá que ser suficiente.",
  ui_story_5034_50340201_29_dialog_content = "Se eu deixar o último celestita do mundo morrer de fome, terei que passar o resto da minha vida na euforia.",
  ui_story_5034_50340201_30_dialog_content = "Obrigado, Corax... Vou saborear cada mordida!",
  ui_story_5034_50340201_31_dialog_content = "(Schewe, Latan... estou a caminho! Só espero que nada de ruim tenha acontecido com eles...)",
  ui_story_5034_50340202_1_dialog_content = "nem percebi a presença deles...",
  ui_story_5034_50340202_2_dialog_content = "Não me diga que eles estão na loja?",
  ui_story_5034_50340202_3_dialog_content = "Vendo óculos de sol!",
  ui_story_5034_50340202_4_dialog_content = "O mais novo estilo, direto da Umbraton!",
  ui_story_5034_50340202_5_dialog_content = "Hum? Essa voz soa muito familiar...",
  ui_story_5034_50340202_6_dialog_content = "Ei, senhor? Posso te interessar em um par de óculos de sol?",
  ui_story_5034_50340202_7_dialog_content = "Eles estão na moda em Umbraton!",
  ui_story_5034_50340202_8_dialog_content = "Hã?",
  ui_story_5034_50340202_9_dialog_content = "Você está dizendo que eu pareço o tipo de cara que precisa de óculos de sol?!",
  ui_story_5034_50340202_10_dialog_content = "Há algo de errado com a aparência dos meus olhos?!",
  ui_story_5034_50340202_11_dialog_content = "N-De jeito nenhum, senhor! Eu não quis dizer assim...",
  ui_story_5034_50340202_12_dialog_content = "Heh... Sabe, ver um pipsqueak como você trabalhando me lembra de mim quando eu era criança.",
  ui_story_5034_50340202_13_dialog_content = "Tudo bem garoto, não diga que eu nunca fiz nada de bom para você. Quanto pelas sombras?",
  ui_story_5034_50340202_14_dialog_content = "Er... 6.000 Nightium o par...",
  ui_story_5034_50340202_15_dialog_content = "Huh? Você tem coragem, garotinha... Tentar convencer as pessoas a comprar óculos de sol por esse preço é exatamente o tipo de coisa que eu fazia quando criança!",
  ui_story_5034_50340202_16_dialog_content = "Infelizmente, você escolheu a pessoa errada para mexer hoje. Deixe-me dar-lhe um gostinho do mundo real...",
  ui_story_5034_50340202_17_dialog_content = "*soluçando*",
  ui_story_5034_50340202_18_dialog_content = "Latão? Isso é você?",
  ui_story_5034_50340202_19_dialog_content = "M-Sr. Navegador!",
  ui_story_5034_50340202_20_dialog_content = "*Solucionando* Estou aqui...",
  ui_story_5034_50340202_21_dialog_content = "Rapaz, é melhor você cuidar da sua vida!",
  ui_story_5034_50340202_22_dialog_content = "E se eu não vou?",
  ui_story_5034_50340202_23_dialog_content = "Conversa muito difícil, para alguém que está sozinho...",
  ui_story_5034_50340202_24_dialog_content = "Quem disse que estou sozinho?",
  ui_story_5034_50340202_25_dialog_content = "Por aqui, Corax! Pólux!",
  ui_story_5034_50340202_26_dialog_content = "O que? Aquela maluca também está aqui?!",
  ui_story_5034_50340202_27_dialog_content = "J-Apenas espere, punk! Eu te pego na próxima!",
  ui_story_5034_50340202_28_dialog_content = "PlayerName... O Sr. Corax também está com você?",
  ui_story_5034_50340202_29_dialog_content = "Ele não deveria estar cuidando das outras crianças na igreja agora?",
  ui_story_5034_50340202_30_dialog_content = "Desculpe, Latan... Eu estava blefando para assustar aquele cara agora. Corax não está aqui.",
  ui_story_5034_50340202_31_dialog_content = "Se o Sr. Corax estivesse aqui, não teríamos que ter tanto medo daquele <color=#FFB400>lojista</color>...",
  ui_story_5034_50340202_32_dialog_content = "(\"Lojista\"? Ela poderia estar falando sobre AQUELE lojista?)",
  ui_story_5034_50340202_33_dialog_content = "De qualquer forma, o que está acontecendo aqui, Latan? Por que aquele cara estava te incomodando agora?",
  ui_story_5034_50340202_34_dialog_content = "E onde está Schewe? não o vejo em lugar nenhum...",
  ui_story_5034_50340202_35_dialog_content = "Eu lhe direi o que estou fazendo mais tarde, Sr. Navegador. Quanto a Schewe, ele está dentro da loja.",
  ui_story_5034_50340202_36_dialog_content = "Aquele onde você comprou o doce hoje cedo...",
  ui_story_5034_50340202_37_dialog_content = "Eu entendo. Não vou perguntar por que você me seguiu por enquanto.",
  ui_story_5034_50340202_38_dialog_content = "Vamos encontrar Schewe primeiro, ok?",
  ui_story_5034_50340202_39_dialog_content = "Beleza!",
  ui_story_5034_50340202_40_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5034_50340202_41_dialog_content = "Deixando minhas mercadorias no chão de novo, não é? Vou ter que adicionar isso à sua dívida também.",
  ui_story_5034_50340202_42_dialog_content = "Honestamente... Você veio aqui para trabalhar por algum dinheiro, mas tudo o que você fez foi acumular dívidas.",
  ui_story_5034_50340202_43_dialog_content = "Se você não puder reabastecer minhas prateleiras adequadamente, sugiro que pare.",
  ui_story_5034_50340202_44_dialog_content = "Caso contrário, você terá cinquenta anos antes de pagar suas dívidas! Hahahaha!",
  ui_story_5034_50340202_45_dialog_content = "Eu... eu posso fazer isso...",
  ui_story_5034_50340202_46_dialog_content = "<size=45>Ah!</size>",
  ui_story_5034_50340202_47_dialog_content = "<color=#e8d9bb>Clang-Clang!</color>",
  ui_story_5034_50340202_48_dialog_content = "Schewe!",
  ui_story_5034_50340202_49_dialog_content = "Você está bem?!",
  ui_story_5034_50340202_50_dialog_content = "Estou bem, Sr. Navegador... Mas deixei cair outra caixa, então o lojista vai adicioná-la à minha dívida novamente...",
  ui_story_5034_50340202_51_dialog_content = "Dívida? O que diabos está acontecendo aqui?",
  ui_story_5034_50340202_52_dialog_content = "Bem, bem, bem... Se não for o Sr. \"Eu nunca vou voltar\", de volta muito mais cedo do que o esperado.",
  ui_story_5034_50340202_53_dialog_content = "Se você quer saber, essa criança me deve muito dinheiro por todos os problemas que me causou.",
  ui_story_5034_50340202_54_dialog_content = "...",
  ui_story_5034_50340202_55_dialog_content = "Se for esse o caso, vamos resolver as coisas da nossa \"transação\" anterior, certo?",
  ui_story_5034_50340301_1_dialog_content = "Muito bem. Como você é um cliente anterior, estou mais do que feliz em fazê-lo. Você gostaria que eu explicasse como essa dívida surgiu?",
  ui_story_5034_50340301_2_dialog_content = "Não, obrigado, acho que vou ouvir desses dois, em vez disso.",
  ui_story_5034_50340301_3_dialog_content = "Schewe, Latan... Podem me dizer exatamente o que está acontecendo aqui? Não se preocupe, você não está em apuros.",
  ui_story_5034_50340301_4_option_content = "Você pode me dizer por que você me seguiu?",
  ui_story_5034_50340301_5_dialog_content = "Desculpe, Sr. Navegador... Só queríamos saber onde você iria comprar os doces.",
  ui_story_5034_50340301_6_dialog_content = "Seguimos você até aqui e vimos o quanto você trabalhou por aquele saco de doces.",
  ui_story_5034_50340301_7_option_content = "Você pode me falar mais sobre essa \"dívida\"?",
  ui_story_5034_50340301_8_dialog_content = "Queríamos fazer o mesmo que você, Sr. Navegador... Também queríamos trabalhar duro para ganhar nossos doces.",
  ui_story_5034_50340301_9_dialog_content = "Mas o trabalho acabou sendo muito mais difícil do que pensávamos...",
  ui_story_5034_50340301_10_dialog_content = "Fui encarregado dos produtos da loja. Meu trabalho era trazer coisas do armazém para a loja e depois organizá-las nas prateleiras.",
  ui_story_5034_50340301_11_dialog_content = "Mas o lojista me disse que eu não tinha permissão para arrastar as caixas no chão, senão suas mercadorias seriam danificadas.",
  ui_story_5034_50340301_12_dialog_content = "Eu não tive escolha a não ser tentar carregar cada caixa, mas as coisas dentro eram tão pesadas...",
  ui_story_5034_50340301_13_dialog_content = "Então, toda vez que eu deixava cair uma caixa, ele adicionava à minha dívida... Ele disse que era para compensar meus erros no trabalho.",
  ui_story_5034_50340301_14_dialog_content = "Mas verifiquei as coisas dentro das caixas e estavam todas bem!",
  ui_story_5034_50340301_15_option_content = "O que você estava fazendo lá fora agora, Latan?",
  ui_story_5034_50340301_16_dialog_content = "O lojista disse que porque eu sou tão fofo, eu deveria sair e vender óculos de sol para as pessoas que passavam pela loja.",
  ui_story_5034_50340301_17_dialog_content = "Mas ninguém nunca para para me ouvir...",
  ui_story_5034_50340301_18_dialog_content = "Exceto por aquele cara com cara de bravo. Ele é o único que parou para ouvir...",
  ui_story_5034_50340301_19_dialog_content = "Mas ele ficava cada vez mais irritado... e eu estava com tanto medo...",
  ui_story_5034_50340301_19X1_dialog_content = "Isso é tudo. Desculpe, PlayerName.",
  ui_story_5034_50340301_20_dialog_content = "Acho que agora entendi. Uma última pergunta...",
  ui_story_5034_50340301_21_option_content = "Por que vocês queriam trabalhar para doces?",
  ui_story_5034_50340301_22_dialog_content = "Se você estava me seguindo o tempo todo, então você deve saber que eu já comprei o doce.",
  ui_story_5034_50340301_23_dialog_content = "Por que você queria trabalhar ainda mais?",
  ui_story_5034_50340301_24_dialog_content = "Bem... Depois que vimos o quanto você trabalhou apenas para nos comprar alguns doces...",
  ui_story_5034_50340301_25_dialog_content = "Não queríamos parecer um casal de garotos egoístas e malcriados.",
  ui_story_5034_50340301_26_dialog_content = "Então decidimos trabalhar muito para podermos dividir nossos ganhos com você e com a Pollux, pois ela sempre cuida de nós.",
  ui_story_5034_50340301_27_dialog_content = "Pollux uma vez nos contou a história de como uma freira cuidou dela no passado.",
  ui_story_5034_50340301_28_dialog_content = "Ela disse que uma das razões pelas quais ela assumiu a responsabilidade pela igreja e acolheu órfãos como nós... foi para mostrar sua gratidão pela bondade daquela freira.",
  ui_story_5034_50340301_29_dialog_content = "Lembro-me do olhar em seu rosto quando ela nos disse isso... Foi tão gentil e caloroso.",
  ui_story_5034_50340301_30_dialog_content = "Foi quando decidi que precisava ser <color=#FFB400>alguém que entende a gratidão</color> também.",
  ui_story_5034_50340301_31_dialog_content = "Alguém grato e caloroso, assim como ela.",
  ui_story_5034_50340301_32_dialog_content = "Eu quero ser assim também... Fazer os outros se sentirem aquecidos, como Pollux e você.",
  ui_story_5034_50340301_33_dialog_content = "Mas parece que tudo o que fizemos foi estragar as coisas...",
  ui_story_5034_50340301_34_dialog_content = "Entendi.",
  ui_story_5034_50340301_35_dialog_content = "Fazendo truques tão sujos em crianças inocentes assim...",
  ui_story_5034_50340301_36_dialog_content = "É assim que as coisas voam em Euphoria?",
  ui_story_5034_50340301_37_dialog_content = "Eu estava simplesmente tentando ensiná-los a assumir a responsabilidade pelas consequências de suas escolhas.",
  ui_story_5034_50340301_38_dialog_content = "Se você pensar bem, a dívida que eles me devem é como a mensalidade da minha aula.",
  ui_story_5034_50340301_39_dialog_content = "*soluçando* PlayerName... estou com medo... quero voltar para a igreja...",
  ui_story_5034_50340301_40_dialog_content = "(Esqueça. É inútil tentar argumentar com esse lojista sem vergonha.)",
  ui_story_5034_50340301_41_dialog_content = "(Preciso encontrar uma maneira de tirar essas crianças daqui primeiro. Mesmo que eu queira me vingar desse cara, devo discutir isso primeiro com Corax.)",
  ui_story_5034_50340301_42_dialog_content = "(Estou sozinho agora, então é melhor se eu não começar nada.)",
  ui_story_5034_50340301_43_dialog_content = "Essas crianças só queriam comprar dois sacos de doces. Eu vou pagar por isso.",
  ui_story_5034_50340301_44_dialog_content = "Basta dar-lhes o doce e deixá-los ir. Vou liquidar o resto de suas dívidas em seu lugar.",
  ui_story_5034_50340301_45_dialog_content = "Você já esqueceu o que aconteceu esta manhã, meu amigo?",
  ui_story_5034_50340301_46_dialog_content = "Tem certeza de que pode comprar esse doce?",
  ui_story_5034_50340301_47_dialog_content = "Heh, você tem alguma coragem, trazendo isso à tona. Claro que não esqueci.",
  ui_story_5034_50340301_48_dialog_content = "Além do mais, encontrei isso impresso na bolsa!",
  ui_story_5034_50340301_49_dialog_content = "Além de vender produtos falsificados, você também está cobrando cem vezes mais do que o preço de varejo sugerido! Eu ainda não acertei as contas com você sobre isso!",
  ui_story_5034_50340301_50_dialog_content = "Hahaha! E daí se você descobrisse? Não me lembro de ter dito que minhas mercadorias eram genuínas, não é?",
  ui_story_5034_50340301_51_dialog_content = "Além disso, esta é a minha loja, e posso definir os preços da maneira que achar melhor.",
  ui_story_5034_50340301_52_dialog_content = "Quanto à nossa transação, você estava disposto a comprar, e eu estava disposto a vender... É assim que os negócios funcionam, você não concorda?",
  ui_story_5034_50340301_53_dialog_content = "Vamos esquecer os doces, PlayerName...",
  ui_story_5034_50340301_54_dialog_content = "Oh, não há como voltar atrás em sua palavra agora. Você pediu duas malas, e agora você tem que pagar por elas.",
  ui_story_5034_50340301_55_dialog_content = "Pare de assustar as crianças já! Eu disse que ia pagar por eles.",
  ui_story_5034_50340301_56_dialog_content = "Faremos exatamente como esta manhã. Vou trabalhar para os dois sacos de doces.",
  ui_story_5034_50340301_57_dialog_content = "Muito bem, mas terá de trabalhar o dobro do que esta manhã.",
  ui_story_5034_50340301_58_dialog_content = "Quanto às crianças, elas devem ficar aqui até você terminar seu trabalho.",
  ui_story_5034_50340301_59_dialog_content = "Não vou arriscar vocês fugindo quando minha cabeça estiver virada.",
  ui_story_5034_50340301_60_dialog_content = "Deixe-nos ajudá-lo, Sr. Navegador.",
  ui_story_5034_50340301_61_dialog_content = "Eu vou ficar bem, Schewe. Vocês dois podem apenas sentar ali e assistir. Já fiz isso uma vez, então não precisa se preocupar.",
  ui_story_5034_50340301_62_dialog_content = "Ah, e aqui está o saco de doces que prometi a você antes. Você pode lanchar enquanto espera por mim, ok?",
  ui_story_5034_50340301_63_dialog_content = "Confie em mim, vou terminar antes que você perceba, e estaremos de volta à igreja em pouco tempo!",
  ui_story_5034_50340302_1_dialog_content = "(Graças à minha experiência da manhã, estou totalmente familiarizado com o trabalho.)",
  ui_story_5034_50340302_2_dialog_content = "(Como resultado, consegui dobrar o trabalho em apenas metade do tempo!)",
  ui_story_5034_50340302_3_dialog_content = "(Acho que é tudo em um dia de trabalho para mim como Astra's Number One Errand Runner... Heheh...)",
  ui_story_5034_50340302_4_dialog_content = "Terminou tão cedo? Acho que eu estava errado em subestimar você, afinal.",
  ui_story_5034_50340302_5_dialog_content = "Chega de conversa fiada. Basta dar as crianças seus doces e deixá-los ir.",
  ui_story_5034_50340302_6_dialog_content = "Não precisa ser rude. Espere aqui, e eu vou buscá-lo.",
  ui_story_5034_50340302_7_dialog_content = "Oh querida, minhas condolências, amigo.",
  ui_story_5034_50340302_8_dialog_content = "Acabei de verificar minhas prateleiras, e parece que os doces estão todos esgotados.",
  ui_story_5034_50340302_9_dialog_content = "O que? Por que você não nos contou antes? Qual foi o sentido de todo aquele trabalho que fiz agora?!",
  ui_story_5034_50340302_10_dialog_content = "Novamente, não há necessidade de ser rude. Você trabalhou para mim duas vezes em um dia. Parece que foi predestinado pelo destino, se é que posso dizer.",
  ui_story_5034_50340302_11_dialog_content = "Além disso, eu nunca sonharia em explorar meus trabalhadores como outros empregadores mesquinhos.",
  ui_story_5034_50340302_12_dialog_content = "Que tal eu te pagar em Nightium por esses dois sacos de doces em vez disso? Isto é Justo?",
  ui_story_5034_50340302_13_dialog_content = "(Bem, eu já consegui pegar alguns doces para as crianças...)",
  ui_story_5034_50340302_14_dialog_content = "(Se eu concordar com a sugestão do lojista, isso significa que ele me deve 6.000 Nightium.)",
  ui_story_5034_50340302_15_dialog_content = "(Isso deve ser mais do que suficiente para eles comprarem outra coisa para Pollux como presente.)",
  ui_story_5034_50340302_16_dialog_content = "Tudo bem, vou aceitar sua oferta.",
  ui_story_5034_50340302_17_dialog_content = "Obrigado pela sua compreensão! Dê-me um momento, e eu estarei de volta com o seu pagamento.",
  ui_story_5034_50340302_18_dialog_content = "Pronto, aqui está. Obrigado novamente por seu trabalho duro!",
  ui_story_5034_50340302_19_dialog_content = "10, 20, 30... Espere, isso é apenas 60 Nightium!",
  ui_story_5034_50340302_20_dialog_content = "O que você está jogando aqui? Não deveria ser 6.000 Nightium?",
  ui_story_5034_50340302_21_dialog_content = "Não há erro, meu amigo. Cada saco vale 30 Nightium, então dois sacos seriam 60 Nightium no total.",
  ui_story_5034_50340302_22_dialog_content = "Mesmo aquelas duas crianças poderiam facilmente fazer as contas.",
  ui_story_5034_50340302_23_dialog_content = "Mas cada saco valia 3.000 Nightium, não 30!",
  ui_story_5034_50340302_24_dialog_content = "Ah... Você esquece as coisas tão facilmente, meu amigo.",
  ui_story_5034_50340302_25_dialog_content = "Você foi quem me disse que cada saco valia apenas 30 Nightium, você sabe.",
  ui_story_5034_50340302_26_dialog_content = "Ver? Caso você tenha esquecido, está impresso aqui na bolsa.",
  ui_story_5034_50340302_27_dialog_content = "Como pode ser tão sem vergonha?!",
  ui_story_5034_50340302_28_dialog_content = "Hmph... Eu acho que depois de passar quase um dia inteiro aqui, você teria pelo menos alguma noção das regras da Euphoria.",
  ui_story_5034_50340302_29_dialog_content = "Regras, regras, regras... Não quero mais ouvir falar das \"regras da Euphoria\"!",
  ui_story_5034_50340302_30_dialog_content = "Você é sempre o beneficiado, então de quem são essas regras?!",
  ui_story_5034_50340302_31_dialog_content = "Hahaha! Você está finalmente começando a entender, meu jovem amigo?",
  ui_story_5034_50340302_32_dialog_content = "Claro que estou sempre do lado vencedor... Porque quem não tem dinheiro nem influência não dita as regras aqui.",
  ui_story_5034_50340302_33_dialog_content = "Cansei de falar sobre isso com vocês... Schewe, Latan, vamos sair daqui.",
  ui_story_5034_50340302_34_dialog_content = "Schewe?",
  ui_story_5034_50340302_35_dialog_content = "Latão?",
  ui_story_5034_50340302_36_dialog_content = "Onde você foi?!",
  ui_story_5034_50340302_37_dialog_content = "E onde você pensa que está indo? Ainda tem a questão da dívida deles, sabe?",
  ui_story_5034_50340302_38_dialog_content = "Onde você está escondendo as crianças? É melhor você não fazer nada com eles!",
  ui_story_5034_50340302_39_dialog_content = "O que decido fazer com eles depende inteiramente de você, meu amigo.",
  ui_story_5034_50340302_40_dialog_content = "Você...",
  ui_story_5034_50340401_1_dialog_content = "O que exatamente eu preciso fazer para você deixar esses dois irem?",
  ui_story_5034_50340401_2_dialog_content = "Sou apenas um simples comerciante com demandas simples. Tudo o que peço é que pague a dívida deles.",
  ui_story_5034_50340401_3_dialog_content = "Mas você compensou completamente essa dívida!",
  ui_story_5034_50340401_4_dialog_content = "Bem, se não quiser pagar, pode esquecer de sair daqui com essas duas crianças.",
  ui_story_5034_50340401_5_dialog_content = "Seu desgraçado...!",
  ui_story_5034_50340401_6_dialog_content = "(Espere... Ele está apenas chegando a mim, ou eu sinto Eclipsites por perto?)",
  ui_story_5034_50340401_7_dialog_content = "(Ali! As cortinas atrás do lojista! É onde eles estão escondidos!)",
  ui_story_5034_50340401_8_dialog_content = "(Ele não deveria estar tão composto se houver Eclipsites aparecendo em sua loja.)",
  ui_story_5034_50340401_9_dialog_content = "(A não ser que...)",
  ui_story_5034_50340401_10_dialog_content = "Você está... escondendo Eclipsites em sua loja?",
  ui_story_5034_50340401_11_dialog_content = "Não adianta mentir. Já senti a presença deles.",
  ui_story_5034_50340401_12_dialog_content = "Oh? Então você é o celestita de quem todos falam.",
  ui_story_5034_50340401_13_dialog_content = "Bem, já que você já descobriu isso, suponho que não há mal nenhum em mostrar a você.",
  ui_story_5034_50340401_14_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5034_50340401_15_dialog_content = "V-você... Como você pode manter as crianças presas com Eclipsites?!",
  ui_story_5034_50340401_16_dialog_content = "Uaaau!!",
  ui_story_5034_50340401_17_dialog_content = "Sr. Navegador! S-Salve-me...!",
  ui_story_5034_50340401_18_dialog_content = "E-Ele disse que se fizéssemos algum barulho, ele diria aos Eclipsitas para nos comer...!",
  ui_story_5034_50340401_19_dialog_content = "Já chega, Latan. Chega de chorar...",
  ui_story_5034_50340401_20_dialog_content = "Já criamos problemas suficientes para o Sr. Navegador...",
  ui_story_5034_50340401_21_dialog_content = "Nada disso é culpa de vocês! A culpa é minha por fazer todas aquelas promessas esta manhã.",
  ui_story_5034_50340401_22_dialog_content = "Não se preocupe! Vou me certificar de levá-lo para casa, são e salvo.",
  ui_story_5034_50340401_23_dialog_content = "Ah... Fazendo ainda mais promessas, estou vendo?",
  ui_story_5034_50340401_24_dialog_content = "Seu bastardo... Você está disposto a jogar fora sua humanidade, tudo por um pouco de dinheiro?!",
  ui_story_5034_50340401_25_dialog_content = "Hahahaha! Você não acha divertido falar sobre coisas como \"humanidade\" e \"decência\" na Euforia de todos os lugares?",
  ui_story_5034_50340401_26_dialog_content = "Além disso, já lhe disse o que precisa ser feito para resgatá-los. Eu não sou completamente sem coração, sabe?",
  ui_story_5034_50340401_27_dialog_content = "Você pode salvá-los... ou não. Sua escolha.",
  ui_story_5034_50340401_28_dialog_content = "(Claro que tenho que salvá-los, mas não posso continuar deixando esse cara ter a vantagem!)",
  ui_story_5034_50340401_29_dialog_content = "(A corda que amarra suas mãos está presa ao pescoço dos Eclipsitas.)",
  ui_story_5034_50340401_30_dialog_content = "(Se eu quiser resgatá-los, também terei que desfazer a corda ao redor dos Eclipsites.)",
  ui_story_5034_50340401_31_dialog_content = "(Parece que vou ter que arriscar. Empreste-me um pouco da sua sorte, Casta...)",
  ui_story_5034_50340401_32_dialog_content = "Já tomei minha decisão.",
  ui_story_5034_50340401_33_dialog_content = "Tão cedo? Muito bom, agora vamos ver se é o correto.",
  ui_story_5034_50340401_34_dialog_content = "Eu decidi...",
  ui_story_5034_50340401_35_dialog_content = "Para fazer isso!",
  ui_story_5034_50340401_36_dialog_content = "Argh! Você... Você acabou de jogar uma pedra em mim?! Meu olho...!",
  ui_story_5034_50340401_37_dialog_content = "Você tinha que vir!",
  ui_story_5034_50340401_38_dialog_content = "(Ainda bem que eu não comi. Corax não estava brincando quando disse que estava meio obsoleto.)",
  ui_story_5034_50340401_39_dialog_content = "(Não importa, não há tempo a perder! Eu tenho que salvar as crianças!)",
  ui_story_5034_50340401_40_dialog_content = "Sr. Navegador!",
  ui_story_5034_50340401_41_dialog_content = "Eu sabia que você nos salvaria!",
  ui_story_5034_50340401_42_dialog_content = "Escutem, vocês dois! Assim que eu desfazer esta corda, você precisa fugir o mais rápido que puder!",
  ui_story_5034_50340401_43_dialog_content = "E não volte atrás por nenhum motivo, entendeu?",
  ui_story_5034_50340401_44_dialog_content = "Mas e voce?",
  ui_story_5034_50340401_45_dialog_content = "Ele usou a mesma corda para amarrar você e os Eclipsites. Para desatar você, terei que libertar os Eclipsitas também.",
  ui_story_5034_50340401_46_dialog_content = "Assim que o fizer, chamarei a atenção deles e correrei na direção oposta. Não se preocupe comigo, eu vou ficar bem!",
  ui_story_5034_50340401_47_dialog_content = "Sr. Navegador...",
  ui_story_5034_50340401_48_dialog_content = "Tudo bem, não temos tempo a perder. Na contagem de três, vocês correm o mais rápido que podem, entendem?",
  ui_story_5034_50340401_49_dialog_content = "Um...",
  ui_story_5034_50340401_50_dialog_content = "Dois...",
  ui_story_5034_50340401_51_dialog_content = "Três!",
  ui_story_5034_50340401_52_dialog_content = "<size=45>Executar!</size>",
  ui_story_5034_50340402_1_dialog_content = "Grr... Graah...",
  ui_story_5034_50340402_2_dialog_content = "Graah...",
  ui_story_5034_50340402_3_dialog_content = "Urgh... Eu não posso continuar deixando eles me perseguirem assim. Vou me cansar eventualmente...",
  ui_story_5034_50340402_4_dialog_content = "Eu preciso pensar em um plano para se livrar deles, e rápido!",
  ui_story_5034_50340402_5_dialog_content = "Espere... Se bem me lembro, aquela rua à frente é a que Corax e eu pegamos para entrar na cidade!",
  ui_story_5034_50340402_6_dialog_content = "Acho que tenho uma ideia!",
  ui_story_5034_50340402_7_dialog_content = "Ei, seu idiota! Você disse que o <color=#FFB400>destino</color> continua nos unindo, certo? Bem, de volta para você!",
  ui_story_5034_50340402_8_dialog_content = "Graah!!",
  ui_story_5034_50340402_9_dialog_content = "Graaaa!!",
  ui_story_5034_50340402_10_dialog_content = "Seu punk, você está se escondendo atrás de mim com Eclipsites em seu rabo?",
  ui_story_5034_50340402_11_dialog_content = "A costa é clara. Você pode sair agora.",
  ui_story_5034_50340402_12_dialog_content = "Uau, você realmente derrubou todos eles... Você não é tão ruim, grandão!",
  ui_story_5034_50340402_13_dialog_content = "Nos encontramos novamente. Não pode me encarar como um homem de verdade, então você recorre a esse tipo de truque sujo?",
  ui_story_5034_50340402_14_dialog_content = "N-Não, não é nada disso! De qualquer forma, eu tenho um lugar para estar agora, então... Tchau!",
  ui_story_5034_50340402_15_dialog_content = "Não tenho palavras para agradecer sua ajuda, grandão! <color=#FFB400>Até que o destino nos junte novamente</color>!!",
  ui_story_5034_50340402_16_dialog_content = "Ei! Oi—!",
  ui_story_5034_50340402_17_dialog_content = "Liga para mim PlayerName! Encontre-me se você estiver em Eraveil, e eu vou te mostrar!",
  ui_story_5034_50340402_18_dialog_content = "(Graças a Deus eu lembrei que a rua estava cheia de bandidos. Eu consegui usá-los para me livrar daqueles Eclipsites!)",
  ui_story_5034_50340402_19_dialog_content = "(Estou tão feliz que tudo correu conforme o planejado, ou então eu estaria em apuros.)",
  ui_story_5034_50340402_20_dialog_content = "Estranho... Parece que não há ninguém dentro da loja.",
  ui_story_5034_50340402_21_dialog_content = "O lojista e o resto de seus Eclipsitas não estão em lugar algum...",
  ui_story_5034_50340402_22_dialog_content = "Oh não... Eles poderiam estar perseguindo Schewe e Latan?!",
  ui_story_5034_50340402_23_dialog_content = "Isso é ruim... eu preciso alcançá-los e—",
  ui_story_5034_50340402_23X1_dialog_content = "<size=45>Ai!</size>",
  ui_story_5034_50340402_24_dialog_content = "Nossa, isso doeu...",
  ui_story_5034_50340402_25_dialog_content = "Por que você parece tão cansado? O que aconteceu?",
  ui_story_5034_50340402_26_dialog_content = "E por que não há ninguém aqui?",
  ui_story_5034_50340402_27_dialog_content = "Casta...? É realmente você?",
  ui_story_5034_50340402_28_dialog_content = "Sim, sou eu. O que aconteceu aqui? E o que está acontecendo com você?",
  ui_story_5034_50340402_29_dialog_content = "Casta! Estou tão feliz que você está aqui...",
  ui_story_5034_50340402_30_dialog_content = "Estamos meio em apuros agora. vou tentar resumir...",
  ui_story_5034_50340402_31_dialog_content = "<color=#e8d9bb>Depois de explicar tudo para Casta...</color>",
  ui_story_5034_50340402_32_dialog_content = "Achei estranho a porta da loja estar escancarada, por isso parei para dar uma olhada. Eu não tinha ideia de que todo aquele drama aconteceu.",
  ui_story_5034_50340402_33_dialog_content = "Sinto muito, Casta... não consegui proteger Schewe e Latan...",
  ui_story_5034_50340402_34_dialog_content = "Agora não é hora de se culpar, especialmente em sua condição.",
  ui_story_5034_50340402_35_dialog_content = "De qualquer forma, você não está mais sozinho. Eu estou aqui agora.",
  ui_story_5034_50340402_36_dialog_content = "Aconteça o que acontecer, podemos encontrar uma solução juntos.",
  ui_story_5034_50340402_37_dialog_content = "Também sabemos para qual direção eles correram, então não se preocupe muito.",
  ui_story_5034_50340402_38_dialog_content = "Isso é euforia, afinal. Eu não vou deixar nada acontecer com aqueles dois.",
  ui_story_5034_50340402_39_dialog_content = "Obrigado, Casta... Não sabia que podia ser tão reconfortante.",
  ui_story_5034_50340402_40_dialog_content = "... Eu não tenho idéia do que você está falando.",
  ui_story_5034_50340402_41_dialog_content = "Tudo bem, vamos indo! Temos que encontrar esses dois, não importa o quê.",
  ui_story_5034_50340402_42_dialog_content = "Lidere o caminho.",
  ui_story_5034_50340501_1_dialog_content = "Eu posso sentir Eclipsites por perto... Esta rua deve ser isso.",
  ui_story_5034_50340501_2_dialog_content = "Eu realmente espero que nada de ruim tenha acontecido com eles, ou então eu...",
  ui_story_5034_50340501_3_dialog_content = "Você disse que eles vieram à procura de trabalho, para que pudessem retribuir a você e ao Pollux, certo?",
  ui_story_5034_50340501_4_dialog_content = "É por isso que você se sente tão responsável pela segurança deles?",
  ui_story_5034_50340501_5_dialog_content = "Sim, mas essa não é a única razão... Se eu não tivesse feito um monte de promessas idealistas, nada disso teria acontecido.",
  ui_story_5034_50340501_6_dialog_content = "Minha boca grande é o que os colocou nessa bagunça para começar. E tudo porque eles queriam trabalhar duro para me comprar doces...",
  ui_story_5034_50340501_7_dialog_content = "É assim que esses dois são, para ser honesto.",
  ui_story_5034_50340501_8_dialog_content = "Nos últimos anos, Pollux e eu recebemos pelo menos setenta ou oitenta órfãos aqui em Euphoria.",
  ui_story_5034_50340501_9_dialog_content = "E embora a maioria deles tenha personalidades muito distintas, esses dois garotos se destacam de uma maneira inesquecível.",
  ui_story_5034_50340501_10_option_content = "O que você quer dizer com \"inesquecível\"?",
  ui_story_5034_50340501_11_dialog_content = "A ligação entre eles é incrível.",
  ui_story_5034_50340501_12_dialog_content = "Latan mudou Schewe para melhor, e Schewe protege Latan a todo custo. Só eles podem fazer essas coisas um pelo outro.",
  ui_story_5034_50340501_13_option_content = "Eu me sinto da mesma forma.",
  ui_story_5034_50340501_14_dialog_content = "Eu sabia que você entenderia.",
  ui_story_5034_50340501_15_dialog_content = "De qualquer forma, eles são muito especiais.",
  ui_story_5034_50340501_16_dialog_content = "Se bem me lembro, Pollux resgatou Schewe de um antro subterrâneo de jogos de azar.",
  ui_story_5034_50340501_17_dialog_content = "Quando ele veio pela primeira vez à igreja, ele se recusou a levantar a cabeça ou olhar alguém nos olhos.",
  ui_story_5034_50340501_18_dialog_content = "E ele sempre falava com os outros de uma maneira muito cortês e lisonjeira, mesmo com crianças mais novas do que ele.",
  ui_story_5034_50340501_19_dialog_content = "Porque naquele antro de jogos de azar, a bajulação era a única maneira de ganhar suas refeições e evitar punições.",
  ui_story_5034_50340501_20_dialog_content = "Ele passou a maior parte de sua vida vivendo com medo.",
  ui_story_5034_50340501_21_dialog_content = "Pollux e eu tentamos de tudo, mas simplesmente não conseguimos atravessar as paredes que ele construiu em torno de si.",
  ui_story_5034_50340501_22_dialog_content = "Então, um dia, Latan chegou à igreja e tudo mudou.",
  ui_story_5034_50340501_23_dialog_content = "<color=#e8d9bb>Há um ano</color>",
  ui_story_5034_50340501_24_dialog_content = "*soluçando*",
  ui_story_5034_50340501_25_dialog_content = "P-Por que você está chorando? É porque eu fiz um mau trabalho envolvendo suas bandagens?",
  ui_story_5034_50340501_26_dialog_content = "Me desculpe... eu não sou bom com esse tipo de coisa...",
  ui_story_5034_50340501_27_dialog_content = "Tenho praticado tanto, mas ainda não consigo fazer tão bem quanto Casta...",
  ui_story_5034_50340501_28_dialog_content = "A culpa é minha... Por favor, não chore...",
  ui_story_5034_50340501_29_dialog_content = "*soluçando* eu... eu não estou chorando por causa disso...",
  ui_story_5034_50340501_30_dialog_content = "É por causa daquele cara com a cicatriz no rosto...",
  ui_story_5034_50340501_31_dialog_content = "Ele disse que teve que cortar meu cabelo para poder fechar a ferida na minha cabeça...",
  ui_story_5034_50340501_32_dialog_content = "Um cara com uma cicatriz no rosto? Você quer dizer Nekoyashiki?",
  ui_story_5034_50340501_33_dialog_content = "Então o que aconteceu? O quê ele fez pra você?",
  ui_story_5034_50340501_34_dialog_content = "Então... Então... Ele cortou minha franja e me deixou assim!",
  ui_story_5034_50340501_35_dialog_content = "*Soluçando* Estou horrível agora... Waaaaaah!",
  ui_story_5034_50340501_36_dialog_content = "Huh? Isso é tudo? Você parece bem! Na verdade, se eu olhar mais de perto... *risadas*",
  ui_story_5034_50340501_37_dialog_content = "Ver! Você está rindo também! Eu sabia, eu pareço uma aberração! Waaaaaah!",
  ui_story_5034_50340501_38_dialog_content = "Não, não é isso! Se alguma coisa, você está ainda mais bonito agora. Sério!",
  ui_story_5034_50340501_39_dialog_content = "V-você está mentindo... Você só está dizendo isso para me fazer sentir melhor, não é?",
  ui_story_5034_50340501_40_dialog_content = "O que?! Mas não estou mentindo para você! É assim que eu realmente me sinto, eu prometo!",
  ui_story_5034_50340501_41_dialog_content = "*funga* Me desculpe, mas posso tocar seu cabelo por um segundo? Se eu fizer isso, e então isso...",
  ui_story_5034_50340501_42_dialog_content = "Espere aqui, vou buscar um espelho!",
  ui_story_5034_50340501_43_dialog_content = "Nós iremos? O que você acha?",
  ui_story_5034_50340501_44_dialog_content = "*Cheira*",
  ui_story_5034_50340501_44X1_dialog_content = "Bem... eu acho que parece um pouco diferente...",
  ui_story_5034_50340501_45_dialog_content = "Está até bonitinho agora...",
  ui_story_5034_50340501_45X1_dialog_content = "(T-Na verdade não há diferença... na verdade eu não fiz nada...)",
  ui_story_5034_50340501_46_dialog_content = "Ah! W-foi estranho para mim dizer isso? Será que os outros vão pensar que eu sou muito esnobe agora?",
  ui_story_5034_50340501_47_dialog_content = "Embora, eu realmente pareço bonito, heehee...",
  ui_story_5034_50340501_48_dialog_content = "Ver? Eu disse que não estava mentindo.",
  ui_story_5034_50340501_49_dialog_content = "Meu nome é Latão. O que é seu?",
  ui_story_5034_50340501_50_dialog_content = "Eu sou... Schewe.",
  ui_story_5034_50340501_51_dialog_content = "Sche-nós!",
  ui_story_5034_50340501_52_dialog_content = "Yay! O nome do meu novo melhor amigo é Sche-we!",
  ui_story_5034_50340501_53_dialog_content = "B-Melhor... amigo?",
  ui_story_5034_50340501_54_dialog_content = "Quer dizer que não quer ser amigos?",
  ui_story_5034_50340501_55_dialog_content = "N-Não, claro que quero ser amigos!",
  ui_story_5034_50340501_56_dialog_content = "Eu serei seu melhor amigo, e você pode ser meu melhor amigo também! Ok?",
  ui_story_5034_50340501_57_dialog_content = "Beleza!",
  ui_story_5034_50340501_58_dialog_content = "Achei que aqueles dois gostassem de brincar juntos. Eu não tinha ideia de que eles tinham esse tipo de passado.",
  ui_story_5034_50340501_59_dialog_content = "Só alguém inocente e sincero como Latan poderia derrubar as paredes que cercam o coração de Schewe... É realmente uma amizade rara.",
  ui_story_5034_50340501_60_dialog_content = "Você está certo, então Schewe não vai deixar nada acontecer com Latan. Ele é um garoto esperto. Não se preocupe muito.",
  ui_story_5034_50340501_61_dialog_content = "Sim... Mas ainda assim, não posso deixar de me sentir um pouco preocupado. Também...",
  ui_story_5034_50340501_62_dialog_content = "Também?",
  ui_story_5034_50340501_63_dialog_content = "Tome cuidado! Há um Eclipse atrás de nós!",
  ui_story_5034_50340501_64_dialog_content = "Grr... Graah...",
  ui_story_5034_50340501_65_dialog_content = "Ei, observe isso.",
  ui_story_5034_50340501_66_dialog_content = "Graaaah—",
  ui_story_5034_50340501_67_dialog_content = "Espere, eu tenho certeza que este Eclipsite se parece com o que estava dentro da loja.",
  ui_story_5034_50340501_68_dialog_content = "Isso significa que estamos no caminho certo. Aqueles dois devem ter passado por aqui em algum momento.",
  ui_story_5034_50340501_69_dialog_content = "Casta, vamos continuar!",
  ui_story_5034_50340501_70_dialog_content = "Entendido.",
  ui_story_5034_50340502_1_dialog_content = "Eu posso sentir os eclipses por perto... Talvez eles tenham perseguido as crianças nesta rua?",
  ui_story_5034_50340502_2_dialog_content = "Merda, não esta rua infestada de bandidos novamente...",
  ui_story_5034_50340502_3_dialog_content = "Apenas relaxe, eles não vão encostar um dedo em você enquanto eu estiver aqui.",
  ui_story_5034_50340502_4_dialog_content = "Nós iremos? Você ainda consegue sentir algum eclipse, ou dizer para onde eles foram?",
  ui_story_5034_50340502_5_dialog_content = "não os sinto mais...",
  ui_story_5034_50340502_6_dialog_content = "Mas se eles passaram por aqui, é possível que tenham sido exterminados por esses bandidos de rua, certo?",
  ui_story_5034_50340502_7_dialog_content = "Então o que devemos fazer agora? Essa foi a nossa única pista...",
  ui_story_5034_50340502_8_dialog_content = "Não se preocupe, com todas essas pessoas ao redor, tenho certeza que alguém deve ter visto aqueles dois.",
  ui_story_5034_50340502_9_dialog_content = "Vamos nos separar e perguntar por aí.",
  ui_story_5034_50340502_10_dialog_content = "Tá bom...",
  ui_story_5034_50340502_11_dialog_content = "Eu sei que você ainda se sente culpado, mas agora nossa prioridade é encontrar as crianças.",
  ui_story_5034_50340502_12_dialog_content = "Você tem razão. Precisamos nos apressar se quisermos salvá-los.",
  ui_story_5034_50340502_13_dialog_content = "Vou perguntar por aí. Vamos nos encontrar aqui assim que aprendermos mais.",
  ui_story_5034_50340502_14_dialog_content = "Soa bem.",
  ui_story_5034_50340502_15_dialog_content = "Ah? Você de novo não!",
  ui_story_5034_50340502_16_dialog_content = "Nossa, você é como uma mosca irritante que não para de zumbir na minha cabeça. O que você está fazendo aqui de novo?",
  ui_story_5034_50340502_17_dialog_content = "Ah, grandão! Graças a Deus você ainda está aqui!",
  ui_story_5034_50340502_18_dialog_content = "Além disso, eu não te disse meu nome? Seu-",
  ui_story_5034_50340502_19_dialog_content = "PlayerName, certo? Eu não esqueci, agora se apresse e me diga o que você quer!",
  ui_story_5034_50340502_20_dialog_content = "Você se lembra daquela garotinha de hoje cedo? Aquele que tentou lhe vender um par de óculos de sol?",
  ui_story_5034_50340502_21_dialog_content = "Você já a viu por aqui?",
  ui_story_5034_50340502_22_dialog_content = "O que, aquele pirralho? Sim, eu a vi há um tempo atrás.",
  ui_story_5034_50340502_23_dialog_content = "Ela fugiu naquela direção com algum outro garotinho.",
  ui_story_5034_50340502_24_dialog_content = "Você é um salva-vidas, grandão! Você deveria pensar em abrir um Biscates aqui na Euphoria, sabia?",
  ui_story_5034_50340502_25_dialog_content = "Tenho que ir agora! Obrigado novamente!",
  ui_story_5034_50340502_26_dialog_content = "O que? Ei-",
  ui_story_5034_50340502_27_dialog_content = "Ele se foi. Maldito punk...",
  ui_story_5034_50340502_28_dialog_content = "*Limpa a garganta* \n<size=45>Se você quiser ficar em Euphoria, eu vou aceitá-lo como meu irmãozinho!</size>",
  ui_story_5034_50340502_29_dialog_content = "<size=45>Parece bom para mim!</size>",
  ui_story_5034_50340502_30_dialog_content = "<size=45>Exceto que posso ser o irmão mais velho!</size>",
  ui_story_5034_50340502_31_dialog_content = "Casta! Eu sei para que lado eles foram!",
  ui_story_5034_50340502_32_dialog_content = "Ótimo, então vamos indo.",
  ui_story_5034_50340502_33_dialog_content = "Beleza!",
  ui_story_5034_50340601_1_dialog_content = "Hum? O que é isso...",
  ui_story_5034_50340601_2_dialog_content = "Espere, como ele já chegou tão longe?",
  ui_story_5034_50340601_3_dialog_content = "Não é tão tarde. Eu ainda consigo...",
  ui_story_5034_50340601_4_dialog_content = "Espere um minuto!",
  ui_story_5034_50340601_5_dialog_content = "Latan, Schewe, não vou deixar que nada aconteça com vocês...",
  ui_story_5034_50340601_6_dialog_content = "<size=45>Eu disse para você esperar!!</size>",
  ui_story_5034_50340601_7_dialog_content = "Não temos tempo a perder, Casta! Se não nos apressarmos—",
  ui_story_5034_50340601_8_dialog_content = "Você poderia apenas se acalmar por um segundo? Dê uma olhada neste!",
  ui_story_5034_50340601_9_dialog_content = "Este é... Este é o doce que dei a eles!",
  ui_story_5034_50340601_10_dialog_content = "E olhe! Tem mais por aqui!",
  ui_story_5034_50340601_11_dialog_content = "Parece que eles estavam deixando cair pedaços de doces enquanto corriam. Talvez eles estivessem deixando um rastro para nós seguirmos?",
  ui_story_5034_50340601_12_dialog_content = "Bem, não importa se eles estavam fazendo isso intencionalmente ou não.",
  ui_story_5034_50340601_13_dialog_content = "Contanto que sigamos o rastro dos doces, tenho certeza de que os encontraremos em pouco tempo.",
  ui_story_5034_50340601_14_dialog_content = "Você está totalmente certo. Desculpe por perder a compostura.",
  ui_story_5034_50340601_15_dialog_content = "É uma coisa boa que você estava aqui para notar o doce. Agora vamos nos apressar e seguir a trilha!",
  ui_story_5034_50340601_16_dialog_content = "Agora espere só um segundo. Talvez não tenhamos que ter tanta pressa, afinal.",
  ui_story_5034_50340601_17_dialog_content = "Se eles escolhessem correr por esta rua, então só consigo pensar em um lugar para onde eles iriam.",
  ui_story_5034_50340601_18_dialog_content = "Você está dizendo que já sabe onde eles estão?",
  ui_story_5034_50340601_19_dialog_content = "A Igreja.",
  ui_story_5034_50340601_20_dialog_content = "Uma das primeiras coisas que ensinamos às crianças é voltarem direto para a igreja se alguma vez se encontrarem em apuros.",
  ui_story_5034_50340601_21_dialog_content = "Mas mesmo assim, há uma chance de eles encontrarem Eclipsites no caminho. Não podemos relaxar ainda!",
  ui_story_5034_50340601_22_dialog_content = "Estou tão preocupado com a segurança deles quanto você, se não mais. Mas eu não quero que você entre em pânico mais do que já está.",
  ui_story_5034_50340601_23_dialog_content = "Também... confio nela.",
  ui_story_5034_50340601_24_dialog_content = "Desde que cheguem perto da igreja, tenho certeza de que ela não vai deixar nada acontecer com eles.",
  ui_story_5034_50340601_25_dialog_content = "Agora vamos nos mexer. Estamos voltando para a <color=#FFB400>igreja</color>.",
  ui_story_5034_50340601_26_dialog_content = "Por que a entrada da igreja é cercada por eclipsitas? A menos que o lojista os tenha perseguido até aqui?",
  ui_story_5034_50340601_27_dialog_content = "Vamos acabar com eles, Casta! Eu o guiarei, e esses Eclipsitas não terão chance contra nós!",
  ui_story_5034_50340601_28_dialog_content = "Eu adoraria, mas...",
  ui_story_5034_50340601_29_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5034_50340601_30_dialog_content = "Eu acho que essa luta pertence a outra pessoa agora.",
  ui_story_5034_50340601_31_dialog_content = "Esses são os monstros que perseguiram vocês dois aqui?",
  ui_story_5034_50340601_32_dialog_content = "Não há mais com o que se preocupar. Latan, Schewe, estão seguros agora.",
  ui_story_5034_50340601_33_dialog_content = "Pollux... prometo que não vou fugir assim de novo...",
  ui_story_5034_50340601_34_dialog_content = "E-foi tudo culpa minha...",
  ui_story_5034_50340601_35_dialog_content = "Você já se desculpou, não foi? A coisa mais importante é que vocês dois estão de volta, sãos e salvos.",
  ui_story_5034_50340601_36_dialog_content = "Venha agora... Sem mais lágrimas, ok?",
  ui_story_5034_50340601_37_dialog_content = "É Pólux! E as crianças também! Estou tão feliz que eles estão seguros.",
  ui_story_5034_50340601_38_dialog_content = "Acha que pode finalmente parar de se preocupar agora?",
  ui_story_5034_50340601_39_dialog_content = "Aqui, isso é para você.",
  ui_story_5034_50340601_40_dialog_content = "Casta... Você pegou todos os doces que vimos no caminho de volta?",
  ui_story_5034_50340601_41_dialog_content = "Você parecia com muita pressa para se importar com eles.",
  ui_story_5034_50340601_42_dialog_content = "Você e as crianças não trabalharam duro por esse doce? Aqui, agora você pode dar a eles.",
  ui_story_5034_50340601_43_dialog_content = "Obrigada! Muito obrigado, Casta!",
  ui_story_5034_50340601_44_dialog_content = "Se você gostasse de doces também... Dessa forma, eu poderia te dar alguns como minha forma de agradecer.",
  ui_story_5034_50340601_45_dialog_content = "Como se eu gostasse de comer algo tão infantil quanto um doce.",
  ui_story_5034_50340601_46_dialog_content = "Maldito seja tudo! Esses Eclipses sem cérebro não entendem uma palavra do que eu digo!",
  ui_story_5034_50340601_47_dialog_content = "Como eles puderam perseguir aqueles dois até aqui?!",
  ui_story_5034_50340601_48_dialog_content = "Eu posso lidar com a perda de dinheiro e mercadorias, mas se aquelas duas mulheres da Raven's Blood descobrirem sobre isso...",
  ui_story_5034_50340601_49_dialog_content = "Grr... Graah...",
  ui_story_5034_50340601_50_dialog_content = "G-Afaste-se de mim!",
  ui_story_5034_50340601_51_dialog_content = "Ei... É o lojista!",
  ui_story_5034_50340601_52_dialog_content = "Como você se atreve a mostrar seu rosto por aqui! Eu não vou deixar você escapar desta vez!",
  ui_story_5034_50340601_53_dialog_content = "Graaaah—",
  ui_story_5034_50340601_54_dialog_content = "Aaaaaah! Alguém me salve!!",
  ui_story_5034_50340601_55_dialog_content = "Salvar você? Você é o único que trouxe todos esses Eclipsites aqui em primeiro lugar! Você fez sua cama, agora durma nela!",
  ui_story_5034_50340601_56_dialog_content = "Eu... eu estava errado! Eu sinto Muito! Estou implorando, por favor me ajude!",
  ui_story_5034_50340601_57_dialog_content = "Eu farei o que você quiser, mas por favor, não deixe que eles me comam vivo!",
  ui_story_5034_50340601_58_dialog_content = "Vingar as crianças seria muito melhor se nós mesmos fizéssemos isso, você não concorda?",
  ui_story_5034_50340601_59_dialog_content = "Você tem toda razão, Casta.",
  ui_story_5034_50340601_60_dialog_content = "Digo que o resgatamos dos Eclipsitas. Assim, podemos fazer com que ele nos pague integralmente... com juros.",
  ui_story_5034_50340602_1_dialog_content = "Alguém se importaria de me dizer o que diabos está acontecendo aqui?",
  ui_story_5034_50340602_2_dialog_content = "Desculpe, Pólux. Isso foi tudo culpa minha.",
  ui_story_5034_50340602_3_dialog_content = "Você vê, o que aconteceu foi...",
  ui_story_5034_50340602_4_dialog_content = "<color=#e8d9bb>E então, expliquei tudo ao Pollux do início ao fim...</color>",
  ui_story_5034_50340602_5_dialog_content = "Tudo bem, entendi agora.",
  ui_story_5034_50340602_6_dialog_content = "Não somos estranhos um para o outro. Tenho certeza que você está ciente de quem está no comando aqui.",
  ui_story_5034_50340602_7_dialog_content = "P-Pollux... Eu juro, eu não queria trazer esses Eclipsites aqui! EU...",
  ui_story_5034_50340602_8_dialog_content = "A menos que... você achasse que alguns lacaios do Eclipsite seriam suficientes para me derrubar?",
  ui_story_5034_50340602_9_dialog_content = "N-Não! Eu juro que não é isso!!",
  ui_story_5034_50340602_10_dialog_content = "É só que eu não fazia ideia daqueles dois pirralhos - quero dizer, aqueles dois clientes valiosos eram da sua igreja...",
  ui_story_5034_50340602_11_dialog_content = "Então o que você está dizendo é que se eles fossem apenas crianças comuns, você não teria nenhum problema em enganá-los ou alimentá-los para Eclipsites? É isso?",
  ui_story_5034_50340602_12_dialog_content = "Eu juro que nunca vou fazer isso de novo! Por favor, me poupe desta vez!",
  ui_story_5034_50340602_13_dialog_content = "Vou esquecer tudo sobre suas dívidas!",
  ui_story_5034_50340602_14_dialog_content = "Ah, e o pagamento deles! Aqui, este é o pagamento por toda a ajuda! Se não for suficiente, sempre posso adicionar mais!",
  ui_story_5034_50340602_15_dialog_content = "Vá em frente, Latan e Schewe. Vocês dois ganharam, então é seu para colecionar.",
  ui_story_5034_50340602_16_dialog_content = "Eu vou, Latan. Espere aqui, ok?",
  ui_story_5034_50340602_17_dialog_content = "Está tudo aqui, Pólux! Nem um único Nightium curto!",
  ui_story_5034_50340602_18_dialog_content = "Ah, mas certamente não é suficiente, sim? O que mais posso lhe oferecer? Doce? Você pode ter tudo isso!",
  ui_story_5034_50340602_19_dialog_content = "Por favor, deixe-me voltar para minha loja, e prometo que enviarei alguém para entregá-lo à sua porta!",
  ui_story_5034_50340602_20_dialog_content = "O que te faz pensar que vamos confiar em você depois de tudo isso?",
  ui_story_5034_50340602_21_dialog_content = "E mesmo que você faça a coisa certa hoje, quem pode dizer que você não começará a enganar as pessoas novamente amanhã?",
  ui_story_5034_50340602_22_dialog_content = "Ooh, em que drama eu tropecei. PlayerName tem um ponto.",
  ui_story_5034_50340602_23_dialog_content = "A euforia pode estar longe do caminho batido, mas mesmo que todos os seus produtos sejam importados, seus preços ainda são muito exorbitantes, chegando a um monopólio.",
  ui_story_5034_50340602_24_dialog_content = "Além do mais, as mercadorias pelas quais você está cobrando um braço e uma perna nem são o negócio real.",
  ui_story_5034_50340602_25_dialog_content = "Nekoyashiki, bastante hipócrita, não somos?",
  ui_story_5034_50340602_26_dialog_content = "Não é assim que você ganha dinheiro também? A única diferença é que você vende informação e eu vendo mercadoria.",
  ui_story_5034_50340602_27_dialog_content = "Você não se sente culpado por nada disso, não é?!",
  ui_story_5034_50340602_28_dialog_content = "D-Eu já não concordei em te dar meu dinheiro e doces em troca da minha segurança?!",
  ui_story_5034_50340602_29_dialog_content = "O que mais você quer de mim?!",
  ui_story_5034_50340602_30_dialog_content = "Bem, já que você está perguntando... eu realmente tenho uma ideia. Se Pollux concordar, nós o pouparemos.",
  ui_story_5034_50340602_31_dialog_content = "Vamos ouvir sua ideia, então.",
  ui_story_5034_50340602_32_dialog_content = "Não queremos nada do seu dinheiro sujo. Você pode guardar tudo para você.",
  ui_story_5034_50340602_33_dialog_content = "Mas você tem que entregar sua loja e deixar Nekoyashiki assumir como seu novo proprietário.",
  ui_story_5034_50340602_34_dialog_content = "Como não podemos garantir que você mudará seus hábitos, o mínimo que podemos fazer é tirar sua loja e deixá-la com alguém que não confie nesses tipos de truques para ganhar dinheiro.",
  ui_story_5034_50340602_35_dialog_content = "Além disso, tenho certeza de que você tem dinheiro suficiente para sair da cidade e tentar a sorte em Umbraton, certo?",
  ui_story_5034_50340602_36_dialog_content = "Tenho certeza de que os comerciantes de lá ficarão felizes em mostrar a você como <color=#FFB400>fazer negócios da maneira certa</color>.",
  ui_story_5034_50340602_37_dialog_content = "Mas levar minha loja é demais, você não acha...?",
  ui_story_5034_50340602_38_dialog_content = "Eu pensei que você disse que estava disposto a fazer qualquer coisa? Ou você está voltando atrás em sua palavra tão rapidamente?",
  ui_story_5034_50340602_39_dialog_content = "Argh... Tudo bem. A loja é toda sua.",
  ui_story_5034_50340602_40_dialog_content = "Agora você pode, por favor, me deixar ir?",
  ui_story_5034_50340602_41_dialog_content = "Nunca nos deixe pegar você fazendo esse tipo de coisa novamente, ou você pode não ter tanta sorte da próxima vez. Entender?",
  ui_story_5034_50340602_42_dialog_content = "Ah, e tenha cuidado no seu caminho de volta. Alguns de seus \"animais de estimação\" ainda podem estar vagando por aí.",
  ui_story_5034_50340602_43_dialog_content = "... Humpf.",
  ui_story_5034_50340602_44_dialog_content = "Você parece particularmente feliz com PlayerNamecondições.",
  ui_story_5034_50340602_45_dialog_content = "Você estava planejando isso, não é...",
  ui_story_5034_50340602_46_dialog_content = "Nada passa por você.",
  ui_story_5034_50340602_47_dialog_content = "Mas eu não esperava que as crianças se envolvessem também. Isso foi minha culpa por ser descuidado, e eu sinto muito.",
  ui_story_5034_50340602_48_dialog_content = "Corri de volta assim que ouvi o que aconteceu. Ainda bem que ele é bem esperto, ou então as crianças poderiam estar ainda mais encrencadas.",
  ui_story_5034_50340602_49_dialog_content = "Onde ele está afinal?",
  ui_story_5034_50340603_1_dialog_content = "Sr. Navegador! Estou tão feliz que os Eclipsitas não te devoram e cuspiu seus ossos!",
  ui_story_5034_50340603_2_dialog_content = "Claro que não... Eu sei que você não quer dizer mais nada com isso, mas deveria escolher suas palavras com mais cuidado, Latan.",
  ui_story_5034_50340603_3_dialog_content = "Enfim, venha dar uma olhada no que tenho aqui!",
  ui_story_5034_50340603_4_dialog_content = "É o doce que deixei para trás!",
  ui_story_5034_50340603_5_dialog_content = "Eu sabia que você iria encontrá-lo, Sr. Navegador!",
  ui_story_5034_50340603_6_dialog_content = "Você é o maior, Sr. Navegador!",
  ui_story_5034_50340603_7_dialog_content = "Não era só eu, sabe? Foi graças a vocês e ao seu raciocínio rápido que consegui seguir sua trilha e encontrá-los.",
  ui_story_5034_50340603_8_dialog_content = "Ainda assim, eu nunca esperei que você os pegasse todos e os devolvesse para nós, Sr. Navegador...",
  ui_story_5034_50340603_9_dialog_content = "Bem, eles importam muito para você, não é? Aqui, pegue-os.",
  ui_story_5034_50340603_10_dialog_content = "Além disso, foi Casta quem pegou o doce, não eu. Se alguém merece seu agradecimento, é ela.",
  ui_story_5034_50340603_11_dialog_content = "Mas Casta odeia doces, ou qualquer coisa doce... Ela só gosta de coisas amargas.",
  ui_story_5034_50340603_12_dialog_content = "De qualquer forma, não é como se tivéssemos esquecido de dar um presente para Casta.",
  ui_story_5034_50340603_13_dialog_content = "É assim mesmo? Eu ainda tenho que agradecê-la adequadamente por me ajudar hoje.",
  ui_story_5034_50340603_14_dialog_content = "Exceto que não tenho ideia de onde devo encontrar algo amargo para ela...",
  ui_story_5034_50340603_15_dialog_content = "Então, o que vocês dois conseguiram para ela? Talvez eu possa emprestar alguma inspiração?",
  ui_story_5034_50340603_16_dialog_content = "Hum...",
  ui_story_5034_50340603_17_dialog_content = "Acho que não há problema em te dizer, já que você nos salvou hoje. Mas é uma surpresa, então não conte a ninguém!",
  ui_story_5034_50340603_18_dialog_content = "Nosso plano é esperar até que ela não esteja olhando... e então surpreendê-la com um grande abraço de urso!",
  ui_story_5034_50340603_19_dialog_content = "Mesmo que ela sempre reclame que é muito quente quando a abraçamos...",
  ui_story_5034_50340603_20_dialog_content = "Eu a vi sorrir para si mesma depois de cada abraço!",
  ui_story_5034_50340603_21_dialog_content = "Se você quer agradecê-la também, Sr. Navegador... por que não dar um abraço nela?",
  ui_story_5034_50340603_22_dialog_content = "Er... acho que vou fingir que não ouvi nada.",
  ui_story_5034_50340603_23_dialog_content = "Você acha que Pollux vai gostar de nossos doces também, Sr. Navegador?",
  ui_story_5034_50340603_24_dialog_content = "Causamos tantos problemas por causa de alguns doces...",
  ui_story_5034_50340603_25_dialog_content = "Definitivamente. Tenho certeza que ela vai gostar muito.",
  ui_story_5034_50340603_26_dialog_content = "Se vocês compartilharem suas coisas favoritas com ela, ela definitivamente apreciará o gesto.",
  ui_story_5034_50340603_27_dialog_content = "Além disso, ela nunca ficaria brava com você pelo que aconteceu hoje.",
  ui_story_5034_50340603_28_dialog_content = "A coisa mais importante para ela, e para nós, é que você esteja são e salvo.",
  ui_story_5034_50340603_29_dialog_content = "Basta pensar nisso - ela não ficou aliviada quando vocês dois voltaram em segurança para a igreja?",
  ui_story_5034_50340603_30_dialog_content = "Se alguma coisa, vocês deveriam estar preocupados comigo, e o que ela vai fazer comigo por causar todos esses problemas em primeiro lugar...",
  ui_story_5034_50340603_31_dialog_content = "Aqui, Sr. Navegador. Pegue metade do meu doce.",
  ui_story_5034_50340603_32_dialog_content = "Hã?",
  ui_story_5034_50340603_33_dialog_content = "Se você der um pouco para Pollux, não há como ela ficar brava com você também!",
  ui_story_5034_50340603_34_dialog_content = "E-Então pegue metade do meu doce também, Sr. Navegador!",
  ui_story_5034_50340603_35_dialog_content = "Isso é um presente de agradecimento para você, Sr. Navegador!",
  ui_story_5034_50340603_36_dialog_content = "Hahaha! Muito obrigado, pessoal. Vou pegar um pedaço de cada um de vocês, ok?",
  ui_story_5034_50340603_37_dialog_content = "Eu vou valorizar o doce que você me deu para todo o sempre!",
  ui_story_5034_50340603_38_dialog_content = "Schewe! Latão! PlayerName!",
  ui_story_5034_50340603_39_dialog_content = "O jantar está pronto, então apresse-se, ou não sobrará nada para você!",
  ui_story_5034_50340603_40_dialog_content = "Vamos, vocês dois. Vamos comer uma boa e suada refeição!",
  ui_story_5034_50340603_41_dialog_content = "Beleza!"
}
return config
